│   └── uiRenderer.js         # 3D UI elements in scene (score billboard, lives display)
│
├── systems/                  # Game subsystems
│   ├── collision.js          # AABB/Sphere collision detection for all entity pairs
│   ├── scoring.js            # Score calculation, combo multiplier, high score persistence
│   └── difficulty.js         # Wave progression, speed scaling, spawn rate adjustment
│
└── ui/                       # Glassmorphism HTML/CSS Overlays
    ├── index.js              # UIManager class (orchestrates all overlays)
    ├── menu.html             # Main menu template (start, controls, credits)
