    this.difficultyManager.setWave(1);

    // Clear and respawn entities
    this.projectilePool.clear();
    this.ufo.reset();
    this.powerUpManager.clear();

    // Reset player
    this.player.reset();

    // Respawn aliens
    this.alienGrid.respawn(1);

