    }

    // Power-ups vs player
    const powerUpCollected = this.powerUpManager.checkPlayerCollision(this.player.getBoundingBox());
    if (powerUpCollected) {
      this.applyPowerUp(powerUpCollected);
    }
  }

  handleAlienHit(alien, projectile) {
    // Calculate score with combo multiplier
    const points = this.scoringSystem.addScore(alien.points * this.scoringSystem.comboMultiplier);

    // Trigger VFX
    alien.destroy(projectile.mesh.position);

    // Audio feedback
    this.audio.synth.playExplosion('small');

    // Update scoring system for combo tracking
    this.scoringSystem.registerKill();
  }

  handleUFODestroyed(projectile) {
    const points = this.ufo.destroy();
    this.scoringSystem.addScore(points);
    this.audio.synth.playExplosion('large');

    // Chance to drop power-up
    if (Math.random() < 0.4) {
      this.powerUpManager.spawn(this.ufo.mesh.position.clone());
    }
  }

  handlePowerUpCollected(powerUp, projectile) {
    powerUp.destroy();
    this.scoringSystem.addScore(50); // Bonus for collecting power-up while it's falling
  }

  applyPowerUp(powerUp) {
    const type = powerUp.type;

    switch (type) {
      case 'spread':
        this.player.setWeaponType('spread');
        break;
      case 'shield':
        this.player.activateShield();
        break;
      case 'rapidfire':
        this.player.setFireRate(0.15); // Faster fire rate
        break;
    }

    this.audio.synth.playPowerUp();
  }

  handlePlayerHitByBomb(bomb) {
    if (this.player.isInvulnerable) return;

    this.lives--;
    this.scoringSystem.resetCombo();

    // Trigger VFX and audio
    this.vfx.cameraShake.addTrauma(15);
    this.vfx.hitStop.trigger(2);
    this.vfx.particles.spawnExplosion(this.player.mesh.position, 30, 0xff0000);
    this.audio.synth.playPlayerHit();

    // Apply invulnerability
    this.player.setInvulnerable(2.0);

    // Update UI
    this.uiManager.updateLives(this.lives);

    if (this.lives <= 0) {
      setTimeout(() => this.handleGameOver(), 1000);
    }
  }

  handlePlayerDeath(reason) {
    this.lives = 0;
    this.scoringSystem.resetCombo();
    this.uiManager.updateLives(0);

    // Big explosion at player position
    this.vfx.particles.spawnExplosion(this.player.mesh.position, 50, 0xff0000);
    this.vfx.cameraShake.addTrauma(20);
    this.vfx.hitStop.trigger(3);
    this.audio.synth.playPlayerHit();

    setTimeout(() => this.handleGameOver(), 1000);
  }

  handleWaveComplete() {
    // Calculate wave bonus based on remaining aliens (none in this case)
    const waveBonus = this.wave * 100;
    this.scoringSystem.addScore(waveBonus, true); // true = isBonus

    // Show victory text for the wave
    this.vfx.floatingText.spawn3D(
      new THREE.Vector3(0, 2, 0),
      `WAVE ${this.wave} COMPLETE!`,
      '#00ff00',
      36
    );

    // Brief pause before next wave
    this.state = 'VICTORY';
    this.uiManager.showWaveComplete(this.score, () => {
      this.startNextWave();
    });
  }

  startNextWave() {
    this.wave++;
    this.difficultyManager.setWave(this.wave);

    // Reset player position but keep power-ups
    this.player.resetPosition();

    // Respawn alien grid with increased difficulty
    this.alienGrid.respawn(this.wave);

    // Clear remaining projectiles
    this.projectilePool.clear();

    // Reset UFO timer
    this.ufo.reset();

    // Clear power-ups
    this.powerUpManager.clear();

    // Resume game
    this.state = 'PLAYING';
    this.uiManager.hideWaveComplete();
  }

  handleGameOver() {
    this.state = 'GAMEOVER';
    this.audio.music.stop();
    this.audio.synth.playGameOver();

    const finalScore = this.scoringSystem.getFinalScore();
    this.uiManager.showGameOver(finalScore, () => {
      this.resetGame();
    });
  }

  resetGame() {
    // Reset game state
    this.score = 0;
    this.lives = 3;
    this.wave = 1;

    // Reset scoring system
    this.scoringSystem.reset();

    // Reset difficulty
    this.difficultyManager.setWave(1);

    // Clear and respawn entities
    this.projectilePool.clear();
    this.ufo.reset();
    this.powerUpManager.clear();

    // Reset player
    this.player.reset();

    // Respawn aliens
    this.alienGrid.respawn(1);

    // Restart music
    this.audio.music.start(this.wave);

    // Return to menu or start playing
    this.state = 'PLAYING';
    this.uiManager.hideGameOver();
  }

  startGame() {
    this.resetGame();
    this.state = 'PLAYING';
    this.uiManager.hideMenu();
    this.audio.music.start(this.wave);
  }

  pauseGame() {
    if (this.state === 'PLAYING') {
      this.state = 'PAUSED';
      this.uiManager.showPause();
      this.audio.music.pause();
    } else if (this.state === 'PAUSED') {
      this.state = 'PLAYING';
      this.uiManager.hidePause();
      this.audio.music.resume();
    }
  }

  returnToMenu() {
    this.state = 'MENU';
    this.audio.music.stop();
    this.uiManager.showMenu();
  }

  render(alpha = 0) {
    // Render is handled by the main renderer in index.js
    // This method exists for potential future interpolation rendering
  }

  setDependencies(vfx, audio) {
    this.vfx = vfx;
    this.audio = audio;
    this.inputController = null; // Set externally

    // Pass VFX and audio to entities
    if (this.player) this.player.setVFXAndAudio(vfx, audio.synth);
    if (this.alienGrid) this.alienGrid.setVFXAndAudio(vfx, audio.synth);
  }

  setInputController(controller) {
    this.inputController = controller;
  }

  // Public getters for UI and other systems
  getScore() {
    return this.scoringSystem.getScore();
  }

  getComboMultiplier() {
    return this.scoringSystem.comboMultiplier;
  }

  getCurrentWave() {
    return this.wave;
  }

  destroy() {
    // Cleanup game resources
    if (this.player) this.player.destroy();
    if (this.alienGrid) this.alienGrid.destroy();
    if (this.projectilePool) this.projectilePool.destroy();
    if (this.ufo) this.ufo.destroy();
    if (this.powerUpManager) this.powerUpManager.destroy();

    // Stop game loop
    cancelAnimationFrame(this.gameLoop);
  }
}

import { createPlayerMesh } from '../rendering/playerMesh.js';
import { lerp, clamp } from '../../shared/math.js';
import { NEON_COLORS, PLAYER_CONSTANTS } from '../../shared/constants.js';

export class PlayerShip {
  constructor(scene, x = 0) {
    this.scene = scene;
    this.x = x;
    this.y = PLAYER_CONSTANTS.Y_POSITION;
    this.width = PLAYER_CONSTANTS.WIDTH;
    this.height = PLAYER_CONSTANTS.HEIGHT;

    this.velocityX = 0;
    this.maxSpeed = PLAYER_CONSTANTS.MAX_SPEED;
    this.acceleration = PLAYER_CONSTANTS.ACCELERATION;
    this.friction = PLAYER_CONSTANTS.FRICTION;

    this.shootCooldown = 0;
    this.invulnerableTime = 0;
    this.isInvulnerable = false;

    this.alive = true;
    this.blinkFrame = 0;
    this.blinkInterval = 0.1;

    // Create mesh
    this.mesh = createPlayerMesh();
    this.scene.add(this.mesh);

    // Power-up state
    this.powerUps = {
      spreadShot: false,
      shield: false,
      rapidFire: false
    };
    this.powerUpTimers = {};
  }

  update(dt, input) {
    if (!this.alive) return;

    // Handle movement input
    let moveLeft = false;
    let moveRight = false;

    if (input.keys.has('ArrowLeft') || input.keys.has('a')) {
      moveLeft = true;
    }
    if (input.keys.has('ArrowRight') || input.keys.has('d')) {
      moveRight = true;
    }

    // Gamepad support
    if (input.gamepad) {
      const axisX = input.gamepad.axes[0];
      if (axisX < -0.3) moveLeft = true;
      if (axisX > 0.3) moveRight = true;
    }

    // Apply acceleration
    if (moveLeft && !moveRight) {
      this.velocityX -= this.acceleration * dt;
    } else if (moveRight && !moveLeft) {
      this.velocityX += this.acceleration * dt;
    }

    // Apply friction
    this.velocityX *= this.friction;

    // Clamp velocity
    this.velocityX = clamp(this.velocityX, -this.maxSpeed, this.maxSpeed);

    // Update position
    this.x += this.velocityX * dt;

    // Boundary collision with elastic bounce
    const boundaryLeft = -PLAYER_CONSTANTS.BOUNDARY_X + this.width / 2;
    const boundaryRight = PLAYER_CONSTANTS.BOUNDARY_X - this.width / 2;

    if (this.x < boundaryLeft) {
      this.x = boundaryLeft;
      this.velocityX *= -0.5; // Bounce with energy loss
    } else if (this.x > boundaryRight) {
      this.x = boundaryRight;
      this.velocityX *= -0.5;
    }

    // Update mesh position
    this.mesh.position.set(this.x, this.y, 0);

    // Shoot cooldown update
    if (this.shootCooldown > 0) {
      const rapidFireMultiplier = this.powerUps.rapidFire ? 2 : 1;
      this.shootCooldown -= dt * rapidFireMultiplier;
    }

    // Invulnerability timer
    if (this.invulnerableTime > 0) {
      this.invulnerableTime -= dt;
      if (this.invulnerableTime <= 0) {
        this.isInvulnerable = false;
        this.mesh.visible = true;
      } else {
        this.handleBlink(dt);
      }
    }

    // Power-up timers
    this.updatePowerUps(dt);
  }

  handleBlink(dt) {
    this.blinkFrame += dt;
    if (this.blinkFrame >= this.blinkInterval) {
      this.blinkFrame = 0;
      this.mesh.visible = !this.mesh.visible;
    }
  }

  updatePowerUps(dt) {
    for (const [powerUp, active] of Object.entries(this.powerUps)) {
      if (!active) continue;

      const timerKey = `${powerUp}Timer`;
      if (!this.powerUpTimers[timerKey]) continue;

      this.powerUpTimers[timerKey] -= dt;

      if (this.powerUpTimers[timerKey] <= 0) {
        this.deactivatePowerUp(powerUp);
      }
    }
  }

  activatePowerUp(type, duration = 10) {
    switch (type) {
      case 'spreadShot':
        this.powerUps.spreadShot = true;
        this.powerUpTimers.spreadShotTimer = duration;
        break;
      case 'shield':
        this.powerUps.shield = true;
        this.powerUpTimers.shieldTimer = duration;
        break;
      case 'rapidFire':
        this.powerUps.rapidFire = true;
        this.powerUpTimers.rapidFireTimer = duration;
        break;
    }
  }

  deactivatePowerUp(type) {
    this.powerUps[type] = false;
    delete this.powerUpTimers[`${type}Timer`];
  }

  canShoot() {
    return this.shootCooldown <= 0 && this.alive;
  }

  shoot() {
    if (!this.canShoot()) return null;

    const rapidFireMultiplier = this.powerUps.rapidFire ? 0.5 : 1;
    this.shootCooldown = PLAYER_CONSTANTS.SHOOT_COOLDOWN * rapidFireMultiplier;

    // Return projectile spawn data
    return {
      x: this.x,
      y: this.y + this.height / 2,
      isPlayerProjectile: true,
      spreadShot: this.powerUps.spreadShot
    };
  }

  takeDamage() {
    if (!this.alive) return false;

    // Shield absorbs damage
    if (this.powerUps.shield) {
      this.deactivatePowerUp('shield');
      return true; // Damage absorbed, player survives
    }

    // Invulnerable frames prevent damage
    if (this.isInvulnerable) {
      return true; // Already invulnerable, no new damage
    }

    this.alive = false;
    this.mesh.visible = false;

    // Grant temporary invulnerability for respawn
    this.invulnerableTime = PLAYER_CONSTANTS.INVULNERABILITY_DURATION;
    this.isInvulnerable = true;

    return false; // Player took damage
  }

  respawn() {
    this.alive = true;
    this.x = 0;
    this.velocityX = 0;
    this.mesh.visible = true;
    this.mesh.position.set(this.x, this.y, 0);

    // Reset power-ups on respawn (optional design choice)
    for (const key of Object.keys(this.powerUps)) {
      this.deactivatePowerUp(key);
    }
  }

  getHitbox() {
    return {
      x: this.x - this.width / 2,
      y: this.y - this.height / 2,
      width: this.width,
      height: this.height
    };
  }

  dispose() {
    this.scene.remove(this.mesh);
    if (this.mesh.geometry) {
      this.mesh.geometry.dispose();
    }
    if (this.mesh.material) {
      this.mesh.material.dispose();
    }
  }
}

import { IndividualAlien } from './alien.js';
import { createAlienMesh, ALIEN_TYPES } from '../rendering/alienMesh.js';
import { NEON_COLORS, BOUNDARY_X, PLAYER_Y } from '../../shared/constants.js';

export class AlienGrid {
  constructor(scene) {
    this.scene = scene;
    this.rows = 5;
    this.cols = 10;
    this.aliens = []; // Flat array of all aliens

    this.direction = 1; // 1 = right, -1 = left
    this.baseSpeed = 2.0;
    this.speedMultiplier = 1.0;
    this.dropDistance = 30;

    this.alienWidth = 40;
    this.alienHeight = 30;
    this.spacingX = 55;
    this.spacingY = 45;

    // Calculate grid center position
    const totalGridWidth = (this.cols - 1) * this.spacingX + this.alienWidth;
    const startX = -totalGridWidth / 2;
    const startY = PLAYER_Y - 80;

    // Create aliens in grid formation
    for (let row = 0; row < this.rows; row++) {
      for (let col = 0; col < this.cols; col++) {
        const type = this.getAlienTypeForRow(row);
        const x = startX + col * this.spacingX;
        const y = startY - row * this.spacingY;

        const alien = new IndividualAlien(type, x, y, scene);
        this.aliens.push(alien);
      }
    }

    // Track alive count for difficulty scaling
    this.initialCount = this.aliens.length;
  }

  getAlienTypeForRow(row) {
    if (row <= 1) return 'squid';
    if (row <= 3) return 'crab';
    return 'octopus';
  }

  update(dt, difficultyMultiplier) {
    // Update speed based on remaining aliens (fewer = faster)
    const aliveCount = this.getAliveCount();
    const progress = (this.initialCount - aliveCount) / this.initialCount;
    this.speedMultiplier = 1.0 + progress * 2.0; // Up to 3x speed

    const moveSpeed = this.baseSpeed * this.speedMultiplier * difficultyMultiplier;

    // Check for edge collision before moving
    let hitLeftEdge = false;
    let hitRightEdge = false;

    for (const alien of this.aliens) {
      if (!alien.alive) continue;

      const rightBound = alien.x + this.alienWidth / 2;
      const leftBound = alien.x - this.alienWidth / 2;

      if (leftBound < -BOUNDARY_X) hitLeftEdge = true;
      if (rightBound > BOUNDARY_X) hitRightEdge = true;
    }

    // Move horizontally
    for (const alien of this.aliens) {
      if (!alien.alive) continue;

      alien.x += moveSpeed * this.direction * dt * 60;
    }

    // Handle edge collision - drop and reverse
    if ((this.direction === 1 && hitRightEdge) || (this.direction === -1 && hitLeftEdge)) {
      this.reverseAndDrop();
    }

    // Update individual alien animations/states
    for (const alien of this.aliens) {
      if (alien.alive) {
        alien.update(dt, this.direction);
      }
    }
  }

  reverseAndDrop() {
    this.direction *= -1;

    // Drop all aliens down
    for (const alien of this.aliens) {
      if (!alien.alive) continue;

      alien.y -= this.dropDistance;

      // Trigger squash animation on drop
      alien.triggerSquash();
    }
  }

  getAliveCount() {
    return this.aliens.filter(a => a.alive).length;
  }

  isAllDead() {
    return this.getAliveCount() === 0;
  }

  hasReachedBottom() {
    for (const alien of this.aliens) {
      if (!alien.alive) continue;

      const bottomY = alien.y - this.alienHeight / 2;
      if (bottomY <= PLAYER_Y + 10) {
        return true;
      }
    }
    return false;
  }

  getAliensForType(type) {
    return this.aliens.filter(a => a.type === type && a.alive);
  }

  // Find random alive alien for shooting
  getRandomShooter() {
    const alive = this.aliens.filter(a => a.alive);
    if (alive.length === 0) return null;

    // Prefer bottom-row aliens, then random from each column's lowest
    const byColumn = {};
    for (const alien of alive) {
      const colIndex = Math.round((alien.x + BOUNDARY_X) / this.spacingX);
      if (!byColumn[colIndex] || alien.y > byColumn[colIndex].y) {
        byColumn[colIndex] = alien;
      }
    }

    const columnShots = Object.values(byColumn);
    if (columnShots.length === 0) return null;

    return columnShots[Math.floor(Math.random() * columnShots.length)];
  }

  destroyAlien(alien) {
    alien.alive = false;
    alien.destroy();
  }

  reset(scene, newDifficultyMultiplier = 1.0) {
    // Dispose old aliens
    for (const alien of this.aliens) {
      alien.dispose();
    }

    // Rebuild grid with increased difficulty
    this.baseSpeed *= newDifficultyMultiplier;
    this.speedMultiplier = 1.0;

    const totalGridWidth = (this.cols - 1) * this.spacingX + this.alienWidth;
    const startX = -totalGridWidth / 2;
    const startY = PLAYER_Y - 80;

    this.aliens = [];

    for (let row = 0; row < this.rows; row++) {
      for (let col = 0; col < this.cols; col++) {
        const type = this.getAlienTypeForRow(row);
        const x = startX + col * this.spacingX;
        const y = startY - row * this.spacingY;

        const alien = new IndividualAlien(type, x, y, scene);
        this.aliens.push(alien);
      }
    }

    this.initialCount = this.aliens.length;
  }

  dispose() {
    for (const alien of this.aliens) {
      alien.dispose();
    }
    this.aliens = [];
  }
}

import { NEON_COLORS, PROJECTILE_CONSTANTS } from '../../shared/constants.js';
import { clamp } from '../../shared/math.js';

export class ProjectilePool {
  constructor(scene) {
    this.scene = scene;
    this.pool = [];
    this.active = [];

    const { MAX_PROJECTILES, GEOMETRY_SIZE } = PROJECTILE_CONSTANTS;

    // Pre-create geometry and material (reused for all projectiles)
    const geometry = new THREE.BoxGeometry(GEOMETRY_SIZE.width, GEOMETRY_SIZE.height, GEOMETRY_SIZE.depth);

    // Player projectile material (cyan glow)
    this.playerMaterial = new THREE.MeshStandardMaterial({
      color: 0x111111,
      emissive: NEON_COLORS.CYAN,
      emissiveIntensity: 2.0,
      metalness: 0.5,
      roughness: 0.3
    });

    // Enemy bomb material (red glow)
    this.bombMaterial = new THREE.MeshStandardMaterial({
      color: 0x111111,
      emissive: NEON_COLORS.RED,
      emissiveIntensity: 2.0,
      metalness: 0.5,
      roughness: 0.3
    });

    // Pre-allocate all projectiles
    for (let i = 0; i < MAX_PROJECTILES; i++) {
      const mesh = new THREE.Mesh(geometry, null); // Material assigned on spawn
      this.pool.push({
        id: i,
        mesh: mesh,
        active: false,
        type: null, // 'player' or 'enemy'
        position: new THREE.Vector3(),
        velocityY: 0,
        hitbox: { x: 0, y: 0, width: GEOMETRY_SIZE.width, height: GEOMETRY_SIZE.height }
      });
    }

    this.geometry = geometry; // Keep reference for disposal later
  }

  spawnPlayerProjectile(x, y) {
    const projectile = this._getFromPool();
    if (!projectile) return null;

    projectile.type = 'player';
    projectile.mesh.material = this.playerMaterial;
    projectile.position.set(x, y, 0);
    projectile.velocityY = PROJECTILE_CONSTANTS.PLAYER_SPEED;
    projectile.hitbox.x = x - PROJECTILE_CONSTANTS.GEOMETRY_SIZE.width / 2;
    projectile.hitbox.y = y;

    projectile.mesh.position.copy(projectile.position);
    projectile.active = true;
    this.active.push(projectile);

    if (!this.scene) {
      // Scene might not be set yet, defer add
      projectile.deferredAdd = true;
    } else {
      this.scene.add(projectile.mesh);
    }

    return projectile;
  }

  spawnEnemyBomb(x, y) {
    const projectile = this._getFromPool();
    if (!projectile) return null;

    projectile.type = 'enemy';
    projectile.mesh.material = this.bombMaterial;
    projectile.position.set(x, y, 0);
    projectile.velocityY = -PROJECTILE_CONSTANTS.ENEMY_SPEED;
    projectile.hitbox.x = x - PROJECTILE_CONSTANTS.GEOMETRY_SIZE.width / 2;
    projectile.hitbox.y = y;

    projectile.mesh.position.copy(projectile.position);
    projectile.active = true;
    this.active.push(projectile);

    if (!this.scene) {
      projectile.deferredAdd = true;
    } else {
      this.scene.add(projectile.mesh);
    }

    return projectile;
  }

  _getFromPool() {
    // First try the pool
    if (this.pool.length > 0) {
      return this.pool.shift();
    }

    // If pool empty, recycle oldest inactive projectile from active array
    // This is a last resort - should not happen with proper cleanup
    const oldestIndex = this.active.findIndex(p => 
      p.type === 'player' && p.position.y > 15 ||
      p.type === 'enemy' && p.position.y < -10
    );

    if (oldestIndex !== -1) {
      const recycled = this.active.splice(oldestIndex, 1)[0];
      this._removeFromScene(recycled);
      return recycled;
    }

    return null; // Pool exhausted
  }

  update(dt, boundaryTop, boundaryBottom) {
    for (let i = this.active.length - 1; i >= 0; i--) {
      const p = this.active[i];

      // Move projectile
      p.position.y += p.velocityY * dt * 60; // Normalize to ~60fps

      // Update mesh position
      p.mesh.position.copy(p.position);

      // Update hitbox
      p.hitbox.y = p.position.y;

      // Check bounds and recycle
      if (p.type === 'player' && p.position.y > boundaryTop) {
        this._recycle(i);
        continue;
      }

      if (p.type === 'enemy' && p.position.y < boundaryBottom) {
        this._recycle(i);
        continue;
      }
    }
  }

  _recycle(index) {
    const projectile = this.active.splice(index, 1)[0];
    this._removeFromScene(projectile);

    projectile.active = false;
    projectile.type = null;
    projectile.mesh.visible = false;
    this.pool.push(projectile);
  }

  _removeFromScene(projectile) {
    if (this.scene && projectile.mesh.parent) {
      this.scene.remove(projectile.mesh);
    }
  }

  getActive() {
    return this.active;
  }

  clearAll() {
    // Recycle all active projectiles back to pool
    while (this.active.length > 0) {
      const p = this.active.pop();
      this._removeFromScene(p);
      p.active = false;
      p.type = null;
      p.mesh.visible = false;
      this.pool.push(p);
    }
  }

  dispose() {
    // Remove all meshes from scene
    const allProjectiles = [...this.active, ...this.pool];
    for (const proj of allProjectiles) {
      if (this.scene && proj.mesh.parent) {
        this.scene.remove(proj.mesh);
      }
    }

    // Dispose geometry and materials
    if (this.geometry) {
      this.geometry.dispose();
      this.geometry = null;
    }

    if (this.playerMaterial) {
      this.playerMaterial.dispose();
      this.playerMaterial = null;
    }

    if (this.bombMaterial) {
      this.bombMaterial.dispose();
      this.bombMaterial = null;
    }

    this.pool = [];
    this.active = [];
  }

  setScene(scene) {
    this.scene = scene;

    // Add any deferred projectiles to scene
    for (const proj of [...this.active, ...this.pool]) {
      if (proj.deferredAdd && proj.active) {
        scene.add(proj.mesh);
        proj.deferredAdd = false;
      }
    }
  }
}

import { createUFOGeometry } from '../rendering/alienMesh.js';
import { NEON_COLORS, UFO_CONSTANTS } from '../../shared/constants.js';

/**
 * UFO Boss Entity - Rare high-value target that traverses the screen
 */
export class UFOBoss {
  constructor(scene) {
    this.scene = scene;

    // Geometry and material (created once, reused via visibility toggle)
    const geometry = createUFOGeometry();
    const material = new THREE.MeshStandardMaterial({
      color: 0x220033,
      emissive: NEON_COLORS.UFO_GLOW,
      emissiveIntensity: 1.5,
      metalness: 0.6,
      roughness: 0.2
    });

    this.mesh = new THREE.Mesh(geometry, material);
    this.mesh.visible = false;
    scene.add(this.mesh);

    // State
    this.active = false;
    this.position = { x: -30, y: UFO_CONSTANTS.Y_POSITION };
    this.speed = UFO_CONSTANTS.TRANSIT_SPEED;
    this.direction = 1;
    this.spawnTimer = 0;
    this.nextSpawnMin = UFO_CONSTANTS.MIN_SPAWN_INTERVAL;
    this.nextSpawnMax = UFO_CONSTANTS.MAX_SPAWN_INTERVAL;

    // Value (randomized per spawn)
    this.points = Math.floor(Math.random() * 150) + 150; // 150-300 points

    // Power-up drop chance
    this.dropPowerUpChance = UFO_CONSTANTS.POWERUP_DROP_CHANCE;
  }

  update(dt, gameWidth) {
    if (!this.active) {
      this.updateSpawnTimer(dt);
      return null; // No power-up dropped
    }

    // Move across screen
    this.position.x += this.speed * this.direction * dt * 60;

    // Update mesh position
    this.mesh.position.set(this.position.x, this.position.y, 0);

    // Check if reached edge
    const halfWidth = gameWidth / 2;
    if (this.position.x > halfWidth || this.position.x < -halfWidth) {
      this.deactivate();
      return null;
    }

    return null;
  }

  updateSpawnTimer(dt) {
    this.spawnTimer += dt * 1000; // Convert to milliseconds

    if (this.spawnTimer >= this.nextSpawnMin) {
      // Random chance to spawn each check
      if (Math.random() < 0.3) {
        this.spawn();
        return;
      }
    }

    // Reset timer occasionally
    if (this.spawnTimer > this.nextSpawnMax * 1.5) {
      this.spawnTimer = 0;
      this.nextSpawnMin = UFO_CONSTANTS.MIN_SPAWN_INTERVAL + Math.random() * 2000;
      this.nextSpawnMax = UFO_CONSTANTS.MAX_SPAWN_INTERVAL + Math.random() * 3000;
    }
  }

  spawn() {
    // Randomize direction and entry point
    this.direction = Math.random() < 0.5 ? 1 : -1;
    this.position.x = this.direction === 1 ? -40 : 40;

    // Reset timer for next potential spawn
    this.spawnTimer = 0;
    this.nextSpawnMin = UFO_CONSTANTS.MIN_SPAWN_INTERVAL + Math.random() * 2000;
    this.nextSpawnMax = UFO_CONSTANTS.MAX_SPAWN_INTERVAL + Math.random() * 3000;

    // Randomize points for this spawn
    this.points = Math.floor(Math.random() * 150) + 150;

    this.active = true;
    this.mesh.visible = true;
    this.mesh.position.set(this.position.x, this.position.y, 0);
  }

  deactivate() {
    this.active = false;
    this.mesh.visible = false;
  }

  destroy(onPoints, onVFX, onAudio) {
    if (!this.active) return null;

    this.deactivate();

    // Award points
    onPoints(this.points);

    // Trigger VFX
    const pos = new THREE.Vector3(this.position.x, this.position.y, 0);
    onVFX(pos);

    // Play sound
    onAudio('ufoDestroy');

    // Check for power-up drop
    if (Math.random() < this.dropPowerUpChance) {
      return this.generatePowerUp();
    }

    return null;
  }

  generatePowerUp() {
    const types = ['spread', 'shield', 'rapidfire'];
    const type = types[Math.floor(Math.random() * types.length)];

    return {
      type: type,
      x: this.position.x,
      y: this.position.y
    };
  }

  getBounds() {
    if (!this.active) return null;

    const halfWidth = UFO_CONSTANTS.WIDTH / 2;
    const halfHeight = UFO_CONSTANTS.HEIGHT / 2;

    return {
      left: this.position.x - halfWidth,
      right: this.position.x + halfWidth,
      top: this.position.y + halfHeight,
      bottom: this.position.y - halfHeight
    };
  }

  dispose() {
    this.mesh.geometry.dispose();
    this.mesh.material.dispose();
    this.scene.remove(this.mesh);
  }
}

