import { NEON_COLORS } from '../../shared/constants.js';

/**
 * PowerUp class - dropped by UFO, provides temporary abilities
 */
export class PowerUp {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.width = 1.5;
    this.height = 1.0;

    // Type: 'spread', 'shield', or 'rapidfire'
    const types = ['spread', 'shield', 'rapidfire'];
    this.type = types[Math.floor(Math.random() * types.length)];

    this.active = true;
    this.fallSpeed = 1.5;

    // Visual properties
    this.color = this.getColorForType();
    this.mesh = null;
    this.blinkTimer = 0;
    this.blinkVisible = true;
  }

  getColorForType() {
    switch (this.type) {
      case 'spread': return NEON_COLORS.PURPLE;
      case 'shield': return NEON_COLORS.CYAN;
      case 'rapidfire': return NEON_COLORS.ORANGE;
      default: return NEON_COLORS.WHITE;
    }
  }

  createMesh() {
    const geometry = new THREE.BoxGeometry(this.width, this.height, 0.5);
    const material = new THREE.MeshStandardMaterial({
      color: 0x111111,
      emissive: this.color,
      emissiveIntensity: 2.0,
      metalness: 0.5,
      roughness: 0.3
    });

    this.mesh = new THREE.Mesh(geometry, material);
    return this.mesh;
  }

  update(dt) {
    if (!this.active) return;

    // Fall downward
    this.y -= this.fallSpeed * dt;

    // Blink effect
    this.blinkTimer += dt;
    if (this.blinkTimer > 0.15) {
      this.blinkTimer = 0;
      this.blinkVisible = !this.blinkVisible;
    }

    // Update mesh position and visibility
    if (this.mesh) {
      this.mesh.position.set(this.x, this.y, 0);
      this.mesh.visible = this.blinkVisible && this.active;
    }
  }

  checkCollision(playerX, playerWidth) {
    if (!this.active) return false;

    const halfPlayer = playerWidth / 2;
    const halfPowerUp = this.width / 2;

    // Simple AABB collision on X axis (Y is fixed for player)
    const playerLeft = playerX - halfPlayer;
    const playerRight = playerX + halfPlayer;
    const powerUpLeft = this.x - halfPowerUp;
    const powerUpRight = this.x + halfPowerUp;

    // Check if player is at the right Y level to collect
    const collectionYThreshold = 2.0;

    if (this.y < collectionYThreshold && 
        !(playerRight < powerUpLeft || playerLeft > powerUpRight)) {
      this.active = false;
      return true;
    }

    return false;
  }

  isOffScreen() {
    return this.y < -15;
  }

  dispose() {
    if (this.mesh) {
      this.mesh.geometry.dispose();
      this.mesh.material.dispose();
      this.mesh = null;
    }
  }
}

/**
 * PowerUpManager - handles spawning and pooling power-ups
 */
export class PowerUpManager {
  constructor(scene, maxPowerUps = 5) {
    this.scene = scene;
    this.maxPowerUps = maxPowerUps;
    this.powerUps = [];
    this.pool = [];

    // Pre-create meshes for pool
    for (let i = 0; i < maxPowerUps; i++) {
      const geometry = new THREE.BoxGeometry(1.5, 1.0, 0.5);
      const material = new THREE.MeshStandardMaterial({
        color: 0x111111,
        emissive: NEON_COLORS.WHITE,
        emissiveIntensity: 2.0,
        metalness: 0.5,
        roughness: 0.3
      });

      const mesh = new THREE.Mesh(geometry, material);
      mesh.visible = false;
      this.scene.add(mesh);

      this.pool.push({
        mesh: mesh,
        geometry: geometry,
        material: material
      });
    }
  }

  spawn(x, y) {
    // Check if we have capacity
    if (this.powerUps.length >= this.maxPowerUps) {
      return null;
    }

    let powerUpData = null;

    if (this.pool.length > 0) {
      powerUpData = this.pool.pop();
    } else {
      // Emergency: create new mesh
      const geometry = new THREE.BoxGeometry(1.5, 1.0, 0.5);
      const material = new THREE.MeshStandardMaterial({
        color: 0x111111,
        emissive: NEON_COLORS.WHITE,
        emissiveIntensity: 2.0
      });
      const mesh = new THREE.Mesh(geometry, material);
      this.scene.add(mesh);
      powerUpData = { mesh, geometry, material };
    }

    const powerUp = new PowerUp(x, y);
    powerUp.mesh = powerUpData.mesh;
    powerUp.mesh.material.emissive.setHex(powerUp.color);
    powerUp.mesh.position.set(x, y, 0);
    powerUp.mesh.visible = true;

    this.powerUps.push({ powerUp, data: powerUpData });

    return powerUp.type; // Return type for audio feedback
  }

  update(dt) {
    for (let i = this.powerUps.length - 1; i >= 0; i--) {
      const item = this.powerUps[i];
      const pu = item.powerUp;

      pu.update(dt);

      // Remove if off screen
      if (pu.isOffScreen()) {
        this.recycle(i, item.data);
      }
    }
  }

  checkCollisions(playerX, playerWidth) {
    for (const item of this.powerUps) {
      const pu = item.powerUp;

      if (pu.checkCollision(playerX, playerWidth)) {
        // Power-up collected - remove it
        const index = this.powerUps.indexOf(item);
        if (index >= 0) {
          this.recycle(index, item.data);
          return pu.type;
        }
      }
    }

    return null;
  }

  recycle(index, data) {
    // Hide mesh and return to pool
    data.mesh.visible = false;
    data.mesh.position.set(9999, 9999, 0);
    this.pool.push(data);

    // Remove from active list
    this.powerUps.splice(index, 1);
  }

  clearAll() {
    while (this.powerUps.length > 0) {
      const item = this.powerUps.pop();
      this.recycle(this.powerUps.length, item.data);
    }
  }

  dispose() {
    // Dispose all pooled meshes
    for (const data of this.pool) {
      if (data.geometry) data.geometry.dispose();
      if (data.material) data.material.dispose();
    }

    // Dispose any remaining active power-ups
    for (const item of this.powerUps) {
      if (item.data.geometry) item.data.geometry.dispose();
      if (item.data.material) item.data.material.dispose();
    }

    this.pool = [];
    this.powerUps = [];
  }
}

import menuHTML from './menu.html?raw';
import hudHTML from './hud.html?raw';
import gameoverHTML from './gameover.html?raw';
import victoryHTML from './victory.html?raw';
import './menu.css';

export class UIManager {
  constructor() {
    this.container = null;
    this.menuOverlay = null;
    this.hudOverlay = null;
    this.gameOverOverlay = null;
    this.victoryOverlay = null;

    this.scoreElement = null;
    this.livesElement = null;
    this.comboElement = null;
    this.waveElement = null;
    this.finalScoreElement = null;
    this.highScoreElement = null;

    this.currentCombo = 0;
    this.highScore = parseInt(localStorage.getItem('spaceInvadersHighScore')) || 0;
  }

  init(container) {
    this.container = container;

    // Create menu overlay
    this.menuOverlay = document.createElement('div');
    this.menuOverlay.className = 'overlay menu-overlay';
    this.menuOverlay.innerHTML = menuHTML;
    this.container.appendChild(this.menuOverlay);

    // Create HUD overlay
    this.hudOverlay = document.createElement('div');
    this.hudOverlay.className = 'overlay hud-overlay hidden';
    this.hudOverlay.innerHTML = hudHTML;
    this.container.appendChild(this.hudOverlay);

    // Create game over overlay
    this.gameOverOverlay = document.createElement('div');
    this.gameOverOverlay.className = 'overlay gameover-overlay hidden';
    this.gameOverOverlay.innerHTML = gameoverHTML;
    this.container.appendChild(this.gameOverOverlay);

    // Create victory overlay
    this.victoryOverlay = document.createElement('div');
    this.victoryOverlay.className = 'overlay victory-overlay hidden';
    this.victoryOverlay.innerHTML = victoryHTML;
    this.container.appendChild(this.victoryOverlay);

    // Cache element references
    this.scoreElement = this.hudOverlay.querySelector('.score-value');
    this.livesElement = this.hudOverlay.querySelector('.lives-value');
    this.comboElement = this.hudOverlay.querySelector('.combo-container');
    this.waveElement = this.hudOverlay.querySelector('.wave-value');
    this.finalScoreElement = this.gameOverOverlay.querySelector('.final-score');
    this.highScoreElement = this.gameOverOverlay.querySelector('.high-score');

    // Bind button events
    const startButton = this.menuOverlay.querySelector('#start-btn');
    if (startButton) {
      startButton.addEventListener('click', () => {
        this.hideMenu();
        return true;
      });
    }

    const restartButton = this.gameOverOverlay.querySelector('#restart-btn');
    if (restartButton) {
      restartButton.addEventListener('click', () => {
        this.reset();
        return true;
      });
    }

    const nextWaveButton = this.victoryOverlay.querySelector('#next-wave-btn');
    if (nextWaveButton) {
      nextWaveButton.addEventListener('click', () => {
        this.hideVictory();
        return true;
      });
    }

    const menuButton = this.gameOverOverlay.querySelector('#menu-btn');
    if (menuButton) {
      menuButton.addEventListener('click', () => {
        this.showMenu();
        return true;
      });
    }

    // Show high score on menu
    const menuHighScore = this.menuOverlay.querySelector('.high-score-display');
    if (menuHighScore) {
      menuHighScore.textContent = `HIGH SCORE: ${this.highScore.toLocaleString()}`;
    }
  }

  showMenu() {
    this.menuOverlay.classList.remove('hidden');
    this.hudOverlay.classList.add('hidden');
    this.gameOverOverlay.classList.add('hidden');
    this.victoryOverlay.classList.add('hidden');

    // Update high score display
    const menuHighScore = this.menuOverlay.querySelector('.high-score-display');
    if (menuHighScore) {
      menuHighScore.textContent = `HIGH SCORE: ${this.highScore.toLocaleString()}`;
    }
  }

  hideMenu() {
    this.menuOverlay.classList.add('hidden');
    this.hudOverlay.classList.remove('hidden');
    this.resetHUD();
  }

  showGameOver(score) {
    this.gameOverOverlay.classList.remove('hidden');
    this.hudOverlay.classList.add('hidden');

    if (this.finalScoreElement) {
      this.finalScoreElement.textContent = score.toLocaleString();
    }
    if (this.highScoreElement) {
      this.highScoreElement.textContent = this.highScore.toLocaleString();
    }

    // Check for new high score
    const newHighScoreMsg = this.gameOverOverlay.querySelector('.new-high-score');
    if (newHighScoreMsg && score > this.highScore) {
      newHighScoreMsg.classList.remove('hidden');
    } else if (newHighScoreMsg) {
      newHighScoreMsg.classList.add('hidden');
    }
  }

  hideGameOver() {
    this.gameOverOverlay.classList.add('hidden');
  }

  showVictory(score, wave) {
    this.victoryOverlay.classList.remove('hidden');
    this.hudOverlay.classList.add('hidden');

    const victoryScore = this.victoryOverlay.querySelector('.victory-score');
    if (victoryScore) {
      victoryScore.textContent = score.toLocaleString();
    }

    const waveText = this.victoryOverlay.querySelector('.wave-text');
    if (waveText) {
      waveText.textContent = `WAVE ${wave} CLEARED`;
    }
  }

  hideVictory() {
    this.victoryOverlay.classList.add('hidden');
    this.hudOverlay.classList.remove('hidden');
  }

  updateScore(score) {
    if (this.scoreElement) {
      this.scoreElement.textContent = score.toLocaleString();
    }
  }

  updateLives(lives) {
    if (this.livesElement) {
      this.livesElement.textContent = '♥'.repeat(Math.max(0, lives));
    }
  }

  updateCombo(combo) {
    this.currentCombo = combo;

    if (this.comboElement) {
      const comboValue = this.comboElement.querySelector('.combo-value');
      const comboGlow = this.comboElement.querySelector('.combo-glow');

      if (combo > 1) {
        this.comboElement.classList.remove('hidden');
        if (comboValue) {
          comboValue.textContent = `${combo}x`;
        }

        // Scale glow based on combo level
        if (comboGlow) {
          const scale = 1 + (combo - 2) * 0.1;
          const intensity = Math.min(combo * 0.3, 2);
          this.comboElement.style.transform = `scale(${scale})`;
          this.comboElement.style.boxShadow = `0 0 ${intensity}px #ff6600, 0 0 ${intensity * 2}px #ff6600`;
        }
      } else {
        this.comboElement.classList.add('hidden');
      }
    }
  }

  updateWave(wave) {
    if (this.waveElement) {
      this.waveElement.textContent = wave;
    }
  }

  resetHUD() {
    this.updateScore(0);
    this.updateLives(3);
    this.updateCombo(1);
    this.updateWave(1);
  }

  reset() {
    this.hideGameOver();
    this.hideVictory();
    this.hudOverlay.classList.remove('hidden');
    this.resetHUD();
  }

  saveHighScore(score) {
    if (score > this.highScore) {
      this.highScore = score;
      localStorage.setItem('spaceInvadersHighScore', score.toString());
      return true;
    }
    return false;
  }

  getHighScore() {
    return this.highScore;
  }

  destroy() {
    if (this.container) {
      this.container.innerHTML = '';
    }
  }
}

import { checkAABB2D, checkSphereCollision } from '../../shared/math.js';

/**
 * Collision System for Space Invaders
 * Handles all entity-to-entity collision detection with proper categorization
 */
export class CollisionSystem {
  constructor() {
    this.playerHitbox = null;
    this.projectiles = []; // Player projectiles
    this.bombs = [];       // Enemy bombs
    this.aliens = [];      // Active aliens for collision checks
    this.powerUps = [];    // Power-up entities
    this.ufo = null;       // UFO entity if active

    // Pre-allocate hitbox objects to avoid allocation during gameplay
    this.tempHitbox1 = { x: 0, y: 0, width: 0, height: 0 };
    this.tempHitbox2 = { x: 0, y: 0, width: 0, height: 0 };

    // Collision results cache
    this.results = {
      playerProjectilesHitAlien: [],
      bombsHitPlayer: false,
      powerUpsCollected: [],
      ufoHit: false
    };
  }

  /**
   * Initialize collision system with current game state
   */
  initialize(player, projectiles, bombs, aliens, powerUps, ufo) {
    this.playerHitbox = player.getHitbox();
    this.projectiles = projectiles;
    this.bombs = bombs;
    this.aliens = aliens;
    this.powerUps = powerUps;
    this.ufo = ufo;

    // Clear results from previous frame
    this.results = {
      playerProjectilesHitAlien: [],
      bombsHitPlayer: false,
      powerUpsCollected: [],
      ufoHit: false
    };
  }

  /**
   * Run all collision checks for the current frame
   * Returns results object with categorized collisions
   */
  update() {
    this.checkProjectileVsAliens();
    this.checkBombsVsPlayer();
    this.checkPowerUpsVsPlayer();
    this.checkUFOVsProjectiles();

    return this.results;
  }

  /**
   * Check player projectiles against all aliens
   */
  checkProjectileVsAliens() {
    const hits = [];

    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const projectile = this.projectiles[i];
      if (!projectile.active) continue;

      const projHitbox = projectile.getHitbox();
      let hitIndex = -1;

      // Check against all active aliens
      for (let j = this.aliens.length - 1; j >= 0; j--) {
        const alien = this.aliens[j];
        if (!alien.active) continue;

        const alienHitbox = alien.getHitbox();

        if (this.aabbCollides(projHitbox, alienHitbox)) {
          hitIndex = j;
          break;
        }
      }

      // If projectile hit an alien, record it
      if (hitIndex >= 0) {
        hits.push({
          projectile: projectile,
          alien: this.aliens[hitIndex],
          impactVelocity: projectile.velocity.y
        });

        // Mark projectile as destroyed
        projectile.active = false;
      }
    }

    this.results.playerProjectilesHitAlien = hits;
  }

  /**
   * Check enemy bombs against player
   */
  checkBombsVsPlayer() {
    let hit = false;

    if (!this.playerHitbox || !this.playerHitbox.active) return;

    for (let i = this.bombs.length - 1; i >= 0; i--) {
      const bomb = this.bombs[i];
      if (!bomb.active) continue;

      const bombHitbox = bomb.getHitbox();

      if (this.aabbCollides(bombHitbox, this.playerHitbox)) {
        hit = true;
        // Mark bomb as destroyed on impact
        bomb.active = false;
        break;
      }
    }

    this.results.bombsHitPlayer = hit;
  }

  /**
   * Check power-ups against player
   */
  checkPowerUpsVsPlayer() {
    const collected = [];

    if (!this.playerHitbox || !this.playerHitbox.active) return;

    for (let i = this.powerUps.length - 1; i >= 0; i--) {
      const powerUp = this.powerUps[i];
      if (!powerUp.active) continue;

      const puHitbox = powerUp.getHitbox();

      if (this.aabbCollides(puHitbox, this.playerHitbox)) {
        collected.push(powerUp);
        powerUp.active = false;
      }
    }

    this.results.powerUpsCollected = collected;
  }

  /**
   * Check UFO against player projectiles
   */
  checkUFOVsProjectiles() {
    if (!this.ufo || !this.ufo.active) return;

    const ufoHitbox = this.ufo.getHitbox();

    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const projectile = this.projectiles[i];
      if (!projectile.active) continue;

      const projHitbox = projectile.getHitbox();

      if (this.aabbCollides(projHitbox, ufoHitbox)) {
        this.results.ufoHit = true;
        projectile.active = false;
        break;
      }
    }
  }

  /**
   * AABB collision check helper
   */
  aabbCollides(a, b) {
    return (
      a.x < b.x + b.width &&
      a.x + a.width > b.x &&
      a.y < b.y + b.height &&
      a.y + a.height > b.y
    );
  }

  /**
   * Get the list of aliens that were hit by projectiles this frame
   */
  getHitAliens() {
    return this.results.playerProjectilesHitAlien.map(hit => hit.alien);
  }

  /**
   * Get the list of projectiles that destroyed aliens (for cleanup)
   */
  getDestroyedProjectiles() {
    return this.results.playerProjectilesHitAlien.map(hit => hit.projectile);
  }

  /**
   * Check if player was hit by a bomb
   */
  isPlayerHit() {
    return this.results.bombsHitPlayer;
  }

  /**
   * Get collected power-ups
   */
  getCollectedPowerUps() {
    return this.results.powerUpsCollected;
  }

  /**
   * Check if UFO was destroyed
   */
  isUFODestroyed() {
    return this.results.ufoHit;
  }

  /**
   * Get impact velocities for VFX feedback (camera shake, hit-stop)
   */
  getImpactVelocities() {
    return this.results.playerProjectilesHitAlien.map(hit => hit.impactVelocity);
  }
}

export default CollisionSystem;

/**
 * ScoringSystem - Manages score calculation, combo multiplier, high scores
 */

export class ScoringSystem {
  constructor() {
    this.score = 0;
    this.highScore = parseInt(localStorage.getItem('spaceInvadersHighScore')) || 0;
    this.comboMultiplier = 1;
    this.consecutiveKills = 0;
    this.maxCombo = 1;

    // Combo thresholds
    this.COMBO_THRESHOLD = 5; // Kills needed for x2 multiplier
    this.MAX_MULTIPLIER = 3;

    // Point values per alien type
    this.POINTS = {
      squid: 30,
      crab: 20,
      octopus: 10,
      ufo: 150
    };
  }

  /**
   * Add score from destroying an entity
   */
  addScore(entityType) {
    let points = this.POINTS[entityType] || 10;

    // UFO has randomized points (150-300)
    if (entityType === 'ufo') {
      points = Math.floor(Math.random() * 150) + 150;
    }

    // Apply combo multiplier
    const totalPoints = points * this.comboMultiplier;
    this.score += totalPoints;

    // Track consecutive kills for combo system
    if (entityType !== 'ufo') {
      this.consecutiveKills++;
      this.updateComboMultiplier();

      if (this.consecutiveKills > this.maxCombo) {
        this.maxCombo = this.consecutiveKills;
      }
    }

    return totalPoints;
  }

  /**
   * Update combo multiplier based on consecutive kills
   */
  updateComboMultiplier() {
    if (this.consecutiveKills >= this.COMBO_THRESHOLD * 2) {
      this.comboMultiplier = this.MAX_MULTIPLIER;
    } else if (this.consecutiveKills >= this.COMBO_THRESHOLD) {
      this.comboMultiplier = 2;
    } else {
      this.comboMultiplier = 1;
    }
  }

  /**
   * Reset combo on player taking damage
   */
  resetCombo() {
    this.consecutiveKills = 0;
    this.comboMultiplier = 1;
  }

  /**
   * Check if new high score achieved
   */
  checkHighScore() {
    return this.score >= this.highScore && this.score > 0;
  }

  /**
   * Save high score to localStorage
   */
  saveHighScore() {
    if (this.checkHighScore()) {
      this.highScore = this.score;
      localStorage.setItem('spaceInvadersHighScore', this.highScore.toString());
      return true;
    }
    return false;
  }

  /**
   * Get formatted score string for display
   */
  getFormattedScore() {
    return this.score.toLocaleString();
  }

  /**
   * Get formatted high score string
   */
  getFormattedHighScore() {
    return this.highScore.toLocaleString();
  }

  /**
   * Get combo display text
   */
  getComboText() {
    if (this.comboMultiplier > 1) {
      return `x${this.comboMultiplier} COMBO! (${this.consecutiveKills} kills)`;
    }
    return '';
  }

  /**
   * Reset scoring for new game
   */
  reset() {
    this.score = 0;
    this.comboMultiplier = 1;
    this.consecutiveKills = 0;
    this.maxCombo = 1;
  }

  /**
   * Get all score data for UI update
   */
  getData() {
    return {
      score: this.score,
      highScore: this.highScore,
      comboMultiplier: this.comboMultiplier,
      consecutiveKills: this.consecutiveKills,
      maxCombo: this.maxCombo
    };
  }
}

/**
 * Difficulty System - Wave progression, speed scaling, spawn rate adjustment
 */

export class DifficultySystem {
  constructor() {
    this.wave = 1;

    // Base values (scale with wave)
    this.baseAlienSpeed = 0.8;
    this.baseBombRate = 0.002; // Per-frame probability per alien

    // Scaling factors
    this.speedScalePerWave = 1.15;
    this.bombRateScalePerWave = 1.2;

    // UFO spawn timing (seconds)
    this.ufoMinInterval = 15;
    this.ufoMaxInterval = 25;
    this.ufoIntervalScale = 0.95; // Gets slightly faster per wave

    // Current computed values
    this.currentAlienSpeed = this.baseAlienSpeed;
    this.currentBombRate = this.baseBombRate;
    this.currentUfoMinInterval = this.ufoMinInterval;
    this.currentUfoMaxInterval = this.ufoMaxInterval;

    this.recalculate();
  }

  /**
   * Recalculate all difficulty values based on current wave
   */
  recalculate() {
    const multiplier = Math.pow(this.speedScalePerWave, this.wave - 1);

    this.currentAlienSpeed = this.baseAlienSpeed * multiplier;
    this.currentBombRate = Math.min(this.baseBombRate * Math.pow(this.bombRateScalePerWave, this.wave - 1), 0.02);

    const ufoMultiplier = Math.pow(this.ufoIntervalScale, this.wave - 1);
    this.currentUfoMinInterval = Math.max(8, this.ufoMinInterval * ufoMultiplier);
    this.currentUfoMaxInterval = Math.max(12, this.ufoMaxInterval * ufoMultiplier);
  }

  /**
   * Advance to next wave
   */
  advanceWave() {
    this.wave++;
    this.recalculate();

    return {
      wave: this.wave,
      alienSpeed: this.currentAlienSpeed,
      bombRate: this.currentBombRate
    };
  }

  /**
   * Get UFO spawn interval range in seconds
   */
  getUfoInterval() {
    const min = this.currentUfoMinInterval;
    const max = this.currentUfoMaxInterval;

    return {
      min: min,
      max: max,
      random: Math.random() * (max - min) + min
    };
  }

  /**
   * Get bomb fire probability for a single alien this frame
   */
  getBombProbability(alienType) {
    // Different alien types have different base probabilities
    const typeMultiplier = {
      'squid': 0.8,
      'crab': 1.5,
      'octopus': 2.0
    };

    return this.currentBombRate * (typeMultiplier[alienType] || 1.0);
  }

  /**
   * Get speed multiplier based on remaining aliens (progressive acceleration)
   */
  getProgressiveSpeedMultiplier(remainingAliens, totalAliens) {
    const ratio = remainingAliens / totalAliens;

    // Speed increases as aliens are destroyed
    // At 100%: 1.0x, at 50%: 1.3x, at 0%: 2.0x
    return 1.0 + (1.0 - ratio) * 1.0;
  }

  /**
   * Get points multiplier for current wave
   */
  getPointsMultiplier() {
    // Slight bonus for higher waves
    return 1.0 + (this.wave - 1) * 0.1;
  }

  /**
   * Reset to initial difficulty
   */
  reset() {
    this.wave = 1;
    this.recalculate();
  }

  /**
   * Get current difficulty state for UI display
   */
  getState() {
    return {
      wave: this.wave,
      alienSpeed: Math.round(this.currentAlienSpeed * 100) / 100,
      bombRate: Math.round(this.currentBombRate * 1000) / 1000,
      ufoIntervalMin: Math.round(this.currentUfoMinInterval),
      ufoIntervalMax: Math.round(this.currentUfoMaxInterval)
    };
  }
}

export default DifficultySystem;

