/**
 * Individual Alien Entity
 * Represents a single alien in the grid with type-specific properties
 */
export class IndividualAlien {
  /**
   * @param {number} row - Row index (0-4)
   * @param {number} col - Column index (0-9)
   * @param {string} type - 'squid', 'crab', or 'octopus'
   */
  constructor(row, col, type) {
    this.row = row;
    this.col = col;
    this.type = type;

    // Type-specific properties
    const typeConfig = ALIEN_CONSTANTS.types[type];
    this.points = typeConfig.points;
    this.fireChance = typeConfig.fireChance;
    this.speedModifier = typeConfig.speedModifier;

    // Position (will be set by AlienGrid)
    this.x = 0;
    this.y = 0;

    // Animation state
    this.animationFrame = 0;
    this.animationTimer = 0;
    this.squashStretch = { x: 1, y: 1 };

    // Mesh reference (created by AlienGrid using InstancedMesh)
    this.meshIndex = -1;

    // State
    this.isDead = false;
    this.deathAnimationTimer = 0;
    this.shouldFire = false;

    // Cached values for rendering
    this.emissiveColor = typeConfig.color;
  }

  /**
   * Update alien state per frame
   * @param {number} dt - Delta time in seconds
   * @returns {boolean} Whether the alien should fire a bomb
   */
  update(dt) {
    if (this.isDead) {
      this.deathAnimationTimer += dt;
      return false;
    }

    // Animation timer for squash/stretch effect
    this.animationTimer += dt * ALIEN_CONSTANTS.ANIMATION_SPEED;

    // Determine animation frame based on timer
    const newFrame = Math.floor(this.animationTimer) % 2;
    if (newFrame !== this.animationFrame) {
      this.animationFrame = newFrame;
      this.triggerAnimationEffect();
    }

    // Random fire decision
    this.shouldFire = Math.random() < this.fireChance * dt * 60;

    return this.shouldFire;
  }

  /**
   * Trigger squash/stretch animation effect
   */
  triggerAnimationEffect() {
    const isFrame0 = this.animationFrame === 0;

    // Squash on frame 0, stretch on frame 1
    if (isFrame0) {
      this.squashStretch.x = 1.15;
      this.squachStretch.y = 0.85;
    } else {
      this.squashStretch.x = 0.85;
      this.squashStretch.y = 1.15;
    }
  }

  /**
   * Set the grid position for this alien
   * @param {number} x - X coordinate in world space
   * @param {number} y - Y coordinate in world space
   */
  setPosition(x, y) {
    this.x = x;
    this.y = y;
  }

  /**
   * Mark alien as dead (triggers death animation)
   */
  kill() {
    this.isDead = true;
    this.deathAnimationTimer = 0;
  }

  /**
   * Get the current scale for rendering with squash/stretch effect
   * @returns {{x: number, y: number, z: number}} Scale values
   */
  getScale() {
    if (this.isDead) {
      // Shrink on death
      const shrink = Math.min(1, this.deathAnimationTimer * 3);
      return { x: shrink, y: shrink, z: shrink };
    }

    // Lerp back to normal scale for smooth animation
    const targetX = this.squashStretch.x;
    const targetY = this.squashStretch.y;

    return {
      x: this.lerp(this.scaleX || 1, targetX, 0.3),
      y: this.lerp(this.scaleY || 1, targetY, 0.3),
      z: 1
    };
  }

  /**
   * Linear interpolation helper
   */
  lerp(start, end, t) {
    return start + (end - start) * t;
  }

  /**
   * Get the instance index for InstancedMesh rendering
   * @returns {number} The mesh index
   */
  getMeshIndex() {
    return this.meshIndex;
  }

  /**
   * Set the instance index for InstancedMesh rendering
   * @param {number} index - The mesh index
   */
  setMeshIndex(index) {
    this.meshIndex = index;
  }

  /**
   * Check if death animation is complete
   * @returns {boolean} True if fully dead and can be removed
   */
  isFullyDead() {
    return this.isDead && this.deathAnimationTimer >= 0.3;
  }
}

/**
 * Alien Type Configuration Helper
 * Returns configuration for a specific alien type
 */
export function getAlienTypeConfig(type) {
  const configs = {
    squid: {
      points: ALIEN_CONSTANTS.types.squid.points,
      fireChance: ALIEN_CONSTANTS.types.squid.fireChance,
      speedModifier: ALIEN_CONSTANTS.types.squid.speedModifier,
      color: NEON_COLORS.SQUID,
      rows: [0, 1]
    },
    crab: {
      points: ALIEN_CONSTANTS.types.crab.points,
      fireChance: ALIEN_CONSTANTS.types.crab.fireChance,
      speedModifier: ALIEN_CONSTANTS.types.crab.speedModifier,
      color: NEON_COLORS.CRAB,
      rows: [2, 3]
    },
    octopus: {
      points: ALIEN_CONSTANTS.types.octopus.points,
      fireChance: ALIEN_CONSTANTS.types.octopus.fireChance,
      speedModifier: ALIEN_CONSTANTS.types.octopus.speedModifier,
      color: NEON_COLORS.OCTOPUS,
      rows: [4]
    }
  };

  return configs[type] || configs.octopus;
}

/**
 * Determine alien type based on row number
 * @param {number} row - Row index (0-4)
 * @returns {string} Alien type name
 */
export function getAlienTypeForRow(row) {
  if (row <= 1) return 'squid';
  if (row <= 3) return 'crab';
  return 'octopus';
}

/**
 * Create the alien grid layout
 * @param {number} rows - Number of rows (default: 5)
 * @param {number} cols - Number of columns (default: 10)
 * @returns {IndividualAlien[]} Array of all aliens in the grid
 */
export function createAlienGrid(rows = 5, cols = 10) {
  const aliens = [];

  for (let row = 0; row < rows; row++) {
    const type = getAlienTypeForRow(row);

    for (let col = 0; col < cols; col++) {
      const alien = new IndividualAlien(row, col, type);
      aliens.push(alien);
    }
  }

  return aliens;
}

export default IndividualAlien;

