export function createStarfield(count = 200) {
  const starsGeometry = new THREE.BufferGeometry();
  const positions = [];
  const colors = [];

  for (let i = 0; i < count; i++) {
    const x = (Math.random() - 0.5) * 100;
    const y = Math.random() * 30 + 5;
    const z = (Math.random() - 0.5) * 50 - 10;

    positions.push(x, y, z);

    // Random star colors (white, cyan, magenta tinted)
    const colorType = Math.random();
    let r, g, b;

    if (colorType < 0.6) {
      // White stars
      const brightness = 0.7 + Math.random() * 0.3;
      r = g = b = brightness;
    } else if (colorType < 0.8) {
      // Cyan tinted
      r = 0.5 + Math.random() * 0.2;
      g = 0.8 + Math.random() * 0.2;
      b = 1.0;
    } else {
      // Magenta tinted
      r = 1.0;
      g = 0.5 + Math.random() * 0.3;
      b = 0.8 + Math.random() * 0.2;
    }

    colors.push(r, g, b);
  }

  starsGeometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  starsGeometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));

  const starsMaterial = new THREE.PointsMaterial({
    size: 0.15,
    vertexColors: true,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending
  });

  const starfield = new THREE.Points(starsGeometry, starsMaterial);

  return { mesh: starfield, positions: starsGeometry.attributes.position.array };
}

export function updateStarfieldParallax(positions, playerX) {
  // Subtle parallax effect based on player position
  for (let i = 0; i < positions.length; i += 3) {
    const depthFactor = (positions[i + 2] + 25) / 45; // Normalize z from -20 to 25
    positions[i] -= playerX * 0.02 * depthFactor;

    // Wrap around screen edges
    if (positions[i] < -50) positions[i] += 100;
    if (positions[i] > 50) positions[i] -= 100;
  }
}

export function createBoundaryWalls() {
  const walls = [];
  const wallMaterial = new THREE.MeshStandardMaterial({
    color: 0x222244,
    emissive: 0x004488,
    emissiveIntensity: 0.3,
    metalness: 0.5,
    roughness: 0.3
  });

  // Left wall
  const leftWall = new THREE.Mesh(new THREE.BoxGeometry(1, 25, 0.5), wallMaterial);
  leftWall.position.set(-14, 12.5, 0);
  walls.push(leftWall);

  // Right wall
  const rightWall = new THREE.Mesh(new THREE.BoxGeometry(1, 25, 0.5), wallMaterial);
  rightWall.position.set(14, 12.5, 0);
  walls.push(rightWall);

  // Bottom barrier (aliens can't pass)
  const bottomBarrier = new THREE.Mesh(new THREE.BoxGeometry(30, 0.5, 0.5), wallMaterial);
  bottomBarrier.position.set(0, -2, 0);
  walls.push(bottomBarrier);

  return walls;
}

export function disposeSceneElements(scene) {
  // Remove all meshes except camera and lights
  scene.children.forEach(child => {
    if (child.isMesh || child.isPoints) {
      scene.remove(child);

      if (child.geometry) {
        child.geometry.dispose();
      }

      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    }
  });
}

import { NEON_COLORS } from '../../shared/constants.js';

/**
 * Creates the player ship mesh using procedural geometry.
 * Returns a Group containing multiple meshes for visual complexity.
 */
export function createPlayerMesh() {
  const group = new THREE.Group();

  // Main body - triangular fighter shape
  const bodyGeometry = new THREE.ConeGeometry(0.6, 1.2, 4);
  const bodyMaterial = new THREE.MeshStandardMaterial({
    color: 0x111111,
    emissive: NEON_COLORS.PLAYER,
    emissiveIntensity: 1.2,
    metalness: 0.5,
    roughness: 0.3,
    flatShading: true
  });
  const body = new THREE.Mesh(bodyGeometry, bodyMaterial);
  body.rotation.x = Math.PI / 2; // Point upward
  body.position.y = 0.3;
  group.add(body);

  // Wings - angular retro-futurism style
  const wingGeometry = new THREE.BoxGeometry(2.4, 0.15, 0.6);
  const wingMaterial = new THREE.MeshStandardMaterial({
    color: 0x111111,
    emissive: NEON_COLORS.PLAYER,
    emissiveIntensity: 0.8,
    metalness: 0.4,
    roughness: 0.4,
    flatShading: true
  });
  const wings = new THREE.Mesh(wingGeometry, wingMaterial);
  wings.position.y = -0.1;
  group.add(wings);

  // Cockpit dome
  const cockpitGeometry = new THREE.SphereGeometry(0.25, 8, 8, 0, Math.PI * 2, 0, Math.PI / 2);
  const cockpitMaterial = new THREE.MeshStandardMaterial({
    color: 0x001133,
    emissive: NEON_COLORS.PLAYER,
    emissiveIntensity: 0.5,
    metalness: 0.8,
    roughness: 0.1,
    transparent: true,
    opacity: 0.9
  });
  const cockpit = new THREE.Mesh(cockpitGeometry, cockpitMaterial);
  cockpit.position.y = 0.4;
  group.add(cockpit);

  // Engine glow - emissive thruster
  const engineGeometry = new THREE.CylinderGeometry(0.15, 0.25, 0.3, 8);
  const engineMaterial = new THREE.MeshStandardMaterial({
    color: 0x0044ff,
    emissive: NEON_COLORS.PLAYER,
    emissiveIntensity: 2.0,
    metalness: 0.9,
    roughness: 0.1
  });
  const engine = new THREE.Mesh(engineGeometry, engineMaterial);
  engine.rotation.x = Math.PI / 2;
  engine.position.y = -0.45;
  group.add(engine);

  // Engine glow core (brighter center)
  const engineCoreGeometry = new THREE.CylinderGeometry(0.08, 0.12, 0.2, 8);
  const engineCoreMaterial = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    emissive: NEON_COLORS.PLAYER,
    emissiveIntensity: 3.0,
    metalness: 1.0,
    roughness: 0.0
  });
  const engineCore = new THREE.Mesh(engineCoreGeometry, engineCoreMaterial);
  engineCore.rotation.x = Math.PI / 2;
  engineCore.position.y = -0.45;
  group.add(engineCore);

  return { mesh: group, bodyMaterial, wingMaterial, cockpitMaterial, engineMaterial, engineCoreMaterial };
}

/**
 * Disposes all materials from a player mesh.
 */
export function disposePlayerMesh(meshObj) {
  if (meshObj.bodyMaterial) meshObj.bodyMaterial.dispose();
  if (meshObj.wingMaterial) meshObj.wingMaterial.dispose();
  if (meshObj.cockpitMaterial) meshObj.cockpitMaterial.dispose();
  if (meshObj.engineMaterial) meshObj.engineMaterial.dispose();
  if (meshObj.engineCoreMaterial) meshObj.engineCoreMaterial.dispose();
}

