/**
 * Procedural alien mesh generator using Canvas API for textures
 * Creates three distinct alien types: Squid (top), Crab (mid), Octopus (bottom)
 */

const ALIEN_SPRITES = {
  squid: [
    '0001111111100',
    '0011111111110',
    '0111111111111',
    '1110111111011',
    '1111111111111',
    '1111101101111',
    '0111111111110',
    '0011001100110',
  ],
  crab: [
    '000001111100000',
    '000011111110000',
    '000111111111000',
    '001111111111100',
    '011111111111110',
    '111111111111111',
    '111111111111111',
    '111110011001111',
    '111110011001111',
    '001110011001110',
  ],
  octopus: [
    '00000011111000000',
    '00001111111110000',
    '00011111111111000',
    '00111111111111100',
    '01111111111111110',
    '11111111111111111',
    '11111111111111111',
    '00111110011111100',
    '00111110011111100',
    '00011001100110000',
  ]
};

const PIXEL_SIZE = 4;
const TEXTURE_PADDING = 2;

/**
 * Generate a CanvasTexture from binary sprite data
 */
function generateAlienTexture(spriteData, color) {
  const rows = spriteData.length;
  const cols = spriteData[0].length;

  const canvas = document.createElement('canvas');
  const width = cols * PIXEL_SIZE + TEXTURE_PADDING * 2;
  const height = rows * PIXEL_SIZE + TEXTURE_PADDING * 2;
  canvas.width = width;
  canvas.height = height;

  const ctx = canvas.getContext('2d');

  // Transparent background
  ctx.fillStyle = 'rgba(0, 0, 0, 0)';
  ctx.fillRect(0, 0, width, height);

  // Draw pixel art
  ctx.fillStyle = color;
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      if (spriteData[row][col] === '1') {
        const x = TEXTURE_PADDING + col * PIXEL_SIZE;
        const y = TEXTURE_PADDING + row * PIXEL_SIZE;
        ctx.fillRect(x, y, PIXEL_SIZE, PIXEL_SIZE);
      }
    }
  }

  // Add subtle glow effect via shadow
  ctx.shadowColor = color;
  ctx.shadowBlur = 2;

  const texture = new THREE.CanvasTexture(canvas);
  texture.magFilter = THREE.NearestFilter;
  texture.minFilter = THREE.NearestFilter;
  texture.colorSpace = THREE.SRGBColorSpace;

  return texture;
}

/**
